class Solution {
public:
    long long minOperations(vector<int>& nums) {
        vector<int> a = nums; long long ans = 0;
        for (int i = 0; i < a.size(); i++)
            if (a[i] == 0) { ans++; for (int j = i; j < a.size(); j++) a[j] ^= 1; }
        return ans;
    }
};

