class Solution {
    public long minOperations(int[] nums) {
        int[] a = nums.clone(); long ans = 0;
        for (int i = 0; i < a.length; i++)
            if (a[i] == 0) { ans++; for (int j = i; j < a.length; j++) a[j] ^= 1; }
        return ans;
    }
}

